head.script:
// 전역 변수로 모든 출석 데이터 저장
scwin.allAttendanceData = [];

// 팝업 레이어 생성 함수
scwin.createPopupLayer = function () {
    var existingPopup = document.getElementById('customAlertPopup');
    if (existingPopup) {
        existingPopup.remove();
    }
    var popupHtml = `
        <div id="customAlertPopup" style="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.6);z-index:9999;display:none;backdrop-filter:blur(5px);">
            <div style="position:absolute;top:50%;left:50%;transform:translate(-50%, -50%);background:white;padding:30px;border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,0.3);min-width:400px;max-width:600px;text-align:center;">
                <div id="popupMessage" style="margin-bottom:25px;font-size:1.1rem;line-height:1.6;color:#2c3e50;white-space:pre-wrap;font-weight:500;"></div>
                <div style="display:flex;gap:15px;justify-content:center;">
                    <button id="popupConfirm" style="background:linear-gradient(135deg, #667eea 0%, #764ba2 100%);color:white;border:none;padding:12px 24px;border-radius:8px;cursor:pointer;font-size:1rem;font-weight:600;min-width:100px;transition:all 0.3s ease;">확인</button>
                    <button id="popupCancel" style="background:#6c757d;color:white;border:none;padding:12px 24px;border-radius:8px;cursor:pointer;font-size:1rem;font-weight:600;min-width:100px;transition:all 0.3s ease;">취소</button>
                </div>
            </div>
        </div>`;
    document.body.insertAdjacentHTML('beforeend', popupHtml);

    // 버튼 호버 효과 추가
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    if (confirmBtn) {
        confirmBtn.addEventListener('mouseenter', function() {
            this.style.transform = 'translateY(-2px)';
            this.style.boxShadow = '0 8px 25px rgba(102, 126, 234, 0.3)';
        });
        confirmBtn.addEventListener('mouseleave', function() {
            this.style.transform = 'translateY(0)';
            this.style.boxShadow = 'none';
        });
    }

    if (cancelBtn) {
        cancelBtn.addEventListener('mouseenter', function() {
            this.style.transform = 'translateY(-2px)';
            this.style.backgroundColor = '#5a6268';
        });
        cancelBtn.addEventListener('mouseleave', function() {
            this.style.transform = 'translateY(0)';
            this.style.backgroundColor = '#6c757d';
        });
    }
};

// 팝업 표시 함수
scwin.showPopup = function (message, isConfirm, callback) {
    var popup = document.getElementById('customAlertPopup');
    if (!popup) {
        scwin.createPopupLayer();
        popup = document.getElementById('customAlertPopup');
    }
    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');
    if (!popup || !messageEl || !confirmBtn || !cancelBtn) {
        alert(message);
        if (callback && !isConfirm) callback();
        return;
    }
    messageEl.textContent = message;
    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function () { popup.style.display = 'none'; if (callback) callback(true); };
        cancelBtn.onclick = function () { popup.style.display = 'none'; if (callback) callback(false); };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function () { popup.style.display = 'none'; if (callback) callback(); };
    }
    popup.style.display = 'block';
};

// 페이지 로드 함수
scwin.onpageload = function () {
    console.log("출석 모듈 페이지 로드 시작");
    scwin.createPopupLayer();

    scwin.ui = {
        sessionListView: $p.getComponentById("grp_sessionListView"),
        detailView: $p.getComponentById("grp_detailView"),
        selectedSessionText: $p.getComponentById("txt_selectedSession")
    };

    scwin.loadSessionList();
    console.log("출석 모듈 페이지 로드 완료");
};

// 세션 목록으로 돌아가는 함수
scwin.showSessionList = function() {
    scwin.ui.detailView.hide();
    scwin.ui.sessionListView.show();
    attendanceList.removeAll();
    dm_stats.setJSON({ totalCount: "0", activeCount: "0", leftCount: "0", avgMinutes: "0" });
};

// 모든 출석 데이터를 로드하여 세션별로 요약하는 함수
scwin.loadSessionList = function() {
    console.log("세션 요약 목록 조회를 시작합니다.");

    var searchOptions = {
        attendanceVo: {
            scSessionId: "", scName: "", scEmail: "", scJoinTime: "",
            pageSize: "9999", pageIndex: "1", sortOrder: "DESC"
        }
    };

    $.ajax({
        url: '/InsWebApp/AttendanceList.pwkjson',
        type: 'POST',
        contentType: 'application/json; charset=utf-8',
        data: JSON.stringify(searchOptions),
        timeout: 10000,
        success: function (response) {
            var allData = [];
            if (response && response.elData && response.elData.attendanceVoList) {
                allData = response.elData.attendanceVoList;
            } else if (response && response.attendanceListVo && response.attendanceListVo.attendanceVoList) {
                allData = response.attendanceListVo.attendanceVoList;
            } else {
                console.error("attendanceVoList를 찾을 수 없습니다. 응답 데이터 구조를 확인하세요:", response);
            }

            if (!allData || allData.length === 0) {
                scwin.showPopup("조회할 출석 데이터가 없습니다.");
                dlt_sessionSummaryList.removeAll();
                return;
            }

            scwin.allAttendanceData = allData;

            const sessionSummary = allData.reduce((acc, item) => {
                const sessionId = item.sessionId || 'N/A_Session';
                if (!acc[sessionId]) {
                    acc[sessionId] = { participants: [], totalMinutes: 0 };
                }
                acc[sessionId].participants.push(item);
                if (item.participationMinutes && !isNaN(item.participationMinutes)) {
                    acc[sessionId].totalMinutes += parseInt(item.participationMinutes, 10);
                }
                return acc;
            }, {});

            const summaryListData = Object.keys(sessionSummary).map(id => {
                const summary = sessionSummary[id];
                const participantCount = summary.participants.length;
                const validTimeEntries = summary.participants.filter(p => p.participationMinutes && !isNaN(p.participationMinutes)).length;
                const avgMinutes = validTimeEntries > 0 ? Math.round(summary.totalMinutes / validTimeEntries) : 0;
                return {
                    sessionId: id,
                    participantCount: participantCount,
                    avgMinutes: avgMinutes
                };
            });

            dlt_sessionSummaryList.setJSON(summaryListData);
            console.log("세션 요약 정보 생성 완료", summaryListData);

            scwin.showSessionList();

        },
        error: function (xhr) {
            scwin.showPopup("서버에서 데이터를 가져오는데 실패했습니다: " + xhr.status);
            dlt_sessionSummaryList.removeAll();
        }
    });
};

// 세션 그리드 클릭 이벤트
scwin.grd_sessions_oncellclick = function(row, col) {
    const selectedSessionId = dlt_sessionSummaryList.getCellData(row, "sessionId");
    if (!selectedSessionId) return;

    console.log(`'${selectedSessionId}' 세션의 상세 정보를 표시합니다.`);

    dm_search.set("scSessionId", selectedSessionId);
    scwin.ui.selectedSessionText.setValue(selectedSessionId);

    const sessionDetails = scwin.allAttendanceData.filter(item => (item.sessionId || 'N/A_Session') === selectedSessionId);

    attendanceList.setJSON(sessionDetails);
    scwin.updateStats(sessionDetails);

    ipt_searchName.setValue("");
    ipt_searchEmail.setValue("");
    ipt_searchDate.setValue("");

    scwin.ui.sessionListView.hide();
    scwin.ui.detailView.show();
};

// 상세 검색 버튼 클릭
scwin.btn_search_onclick = function () {
    const selectedSessionId = dm_search.get("scSessionId");
    const searchName = ipt_searchName.getValue().toLowerCase();
    const searchEmail = ipt_searchEmail.getValue().toLowerCase();
    const searchDate = ipt_searchDate.getValue();

    if (!selectedSessionId) {
        scwin.showPopup("세션이 선택되지 않았습니다.");
        return;
    }

    const filteredData = scwin.allAttendanceData.filter(item => {
        const itemSessionId = item.sessionId || 'N/A_Session';
        if (itemSessionId !== selectedSessionId) {
            return false;
        }

        const nameMatch = !searchName || (item.name && item.name.toLowerCase().includes(searchName));
        const emailMatch = !searchEmail || (item.email && item.email.toLowerCase().includes(searchEmail));
        const dateMatch = !searchDate || (item.joinTime && item.joinTime.substring(0, 10).replace(/-/g, '') === searchDate);

        return nameMatch && emailMatch && dateMatch;
    });

    attendanceList.setJSON(filteredData);
    scwin.updateStats(filteredData);

    if(filteredData.length === 0) {
        scwin.showPopup("조건에 맞는 데이터가 없습니다.");
    }
};

// 상세 검색 조건 초기화
scwin.btn_reset_onclick = function() {
    ipt_searchName.setValue("");
    ipt_searchEmail.setValue("");
    ipt_searchDate.setValue("");

    const selectedSessionId = dm_search.get("scSessionId");
    const sessionDetails = scwin.allAttendanceData.filter(item => (item.sessionId || 'N/A_Session') === selectedSessionId);
    attendanceList.setJSON(sessionDetails);
    scwin.updateStats(sessionDetails);

    scwin.showPopup("검색 조건이 초기화되었습니다.");
};

// 정렬 기능
scwin.setSortOrder_onclick = function (order) {
    dm_search.set("sortOrder", order);
    var currentData = attendanceList.getAllJSON();
    currentData.sort(function(a, b) {
        var timeA = new Date(a.joinTime).getTime();
        var timeB = new Date(b.joinTime).getTime();
        return order === 'ASC' ? timeA - timeB : timeB - timeA;
    });
    attendanceList.setJSON(currentData);
};

// 통계 업데이트 함수
scwin.updateStats = function (data) {
    var total = data.length;
    var active = 0;
    var totalMinutes = 0;
    var validCount = 0;

    for (var i = 0; i < data.length; i++) {
        var item = data[i];
        if (item.status === "참여중") {
            active++;
        }
        if (item.participationMinutes && !isNaN(item.participationMinutes)) {
            totalMinutes += parseInt(item.participationMinutes, 10);
            validCount++;
        }
    }

    var left = total - active;
    var avgMinutes = validCount > 0 ? Math.round(totalMinutes / validCount) : 0;

    dm_stats.set("totalCount", total);
    dm_stats.set("activeCount", active);
    dm_stats.set("leftCount", left);
    dm_stats.set("avgMinutes", avgMinutes);
};

// CSV 다운로드 함수
scwin.btn_downloadCSV_onclick = function () {
    if (attendanceList.getTotalRow() === 0) {
        scwin.showPopup("다운로드할 데이터가 없습니다.");
        return;
    }
    try {
        var data = attendanceList.getAllJSON();
        var csvContent = '\ufeff';
        csvContent += '번호,세션ID,참여자명,이메일,접속IP,입장시간,퇴장시간,참여시간(분),상태\n';
        for (var i = 0; i < data.length; i++) {
            var row = data[i];
            csvContent += (i + 1) + ',';
            csvContent += '"' + (row.sessionId || '') + '",';
            csvContent += '"' + (row.name || '') + '",';
            csvContent += '"' + (row.email || '') + '",';
            csvContent += '"' + (row.ipAddress || '') + '",';
            csvContent += '"' + (row.joinTime || '') + '",';
            csvContent += '"' + (row.leaveTime || '진행중') + '",';
            csvContent += '"' + (row.participationMinutes || '-') + '",';
            csvContent += '"' + (row.status || '') + '"\n';
        }

        var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        var link = document.createElement('a');
        var url = URL.createObjectURL(blob);
        link.setAttribute('href', url);

        var sessionId = dm_search.get("scSessionId").replace(/[^a-zA-Z0-9]/g, '_') || "선택세션";
        var now = new Date();
        var dateStr = now.getFullYear() + String(now.getMonth() + 1).padStart(2, '0') + String(now.getDate()).padStart(2, '0');
        link.setAttribute('download', '출석현황_' + sessionId + '_' + dateStr + '.csv');

        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        scwin.showPopup("CSV 파일이 다운로드되었습니다.");
    } catch (error) {
        console.error("CSV 다운로드 중 오류:", error);
        scwin.showPopup("CSV 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};
